<?php
function heading(string $tag,string $title,string $subtitle): void { echo '<section class="page-heading"><span class="eyebrow">'.e($tag).'</span><h1>'.e($title).'</h1><p>'.e($subtitle).'</p></section>'; }
function action_button(string $action,int $id,string $label,array $extra=[]): void { echo '<form method="post" class="inline">'.csrf_field().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.$id.'">'; foreach ($extra as $k=>$v) echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">'; echo '<button class="button small secondary">'.e($label).'</button></form>'; }
function empty_state(string $message): void { echo '<div class="empty">'.e($message).'</div>'; }
function badge(string $value): string { return '<span class="badge '.e($value).'">'.e(ucfirst($value)).'</span>'; }
function input(string $name,string $label,string $type='text',string $value='',bool $required=true): void { echo '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.($required?'required':'').($type==='password'?' minlength="12" maxlength="128" autocomplete="current-password"':'').'></label>'; }
