heading('THE FINAL WHISTLE','Every result tells a story.','Recorded match scores and club standings. Points: win 3, draw 1, loss 0.');
$matches=rows('SELECT e.*,c.name club,t.name tournament FROM events e JOIN clubs c ON c.id=e.club_id LEFT JOIN tournaments t ON t.id=e.tournament_id WHERE e.kind="match" AND e.home_score IS NOT NULL ORDER BY e.starts_at DESC');
$standings=rows('SELECT c.name,COUNT(e.id) played,COALESCE(SUM(e.home_score>e.away_score),0) wins,COALESCE(SUM(e.home_score=e.away_score),0) draws,COALESCE(SUM(e.home_score<e.away_score),0) losses,COALESCE(SUM(CASE WHEN e.home_score>e.away_score THEN 3 WHEN e.home_score=e.away_score THEN 1 ELSE 0 END),0) points FROM clubs c JOIN events e ON e.club_id=c.id AND e.kind="match" AND e.home_score IS NOT NULL GROUP BY c.id,c.name ORDER BY points DESC,wins DESC');?>
<section class="content"><div class="grid two"><?php foreach($matches as $m):?><article class="card score-card"><span class="eyebrow"><?=e($m['tournament']??$m['title'])?></span><h3><?=e($m['club'])?> <span class="score"><?=e($m['home_score'].' : '.$m['away_score'])?></span> <?=e($m['opponent'])?></h3><p><?=e(when($m['starts_at']).' · '.$m['location'])?></p></article><?php endforeach;?></div><?php if(!$matches) empty_state('Results will appear after an administrator records match scores.');?><h2>Club performance standings</h2><p>Campus club records across recorded matches; this is not a tournament bracket.</p><div class="table-wrap"><table><thead><tr><th>Club</th><th>Played</th><th>Wins</th><th>Draws</th><th>Losses</th><th>Points</th></tr></thead><tbody><?php foreach($standings as $s):?><tr><?php foreach($s as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section>
