heading('SPORTS OFFICE INSIGHTS','Participation with perspective.','Membership, attendance, tournament rosters, and an auditable record of administration.');?>
<section class="content"><div class="section-heading"><h2>Club participation</h2><button class="button secondary" id="print-report">Print / save PDF</button></div><div class="table-wrap"><table><thead><tr><th>Club</th><th>Approved members</th><th>Session registrations</th><th>Attended</th></tr></thead><tbody><?php foreach(rows('SELECT c.name,(SELECT COUNT(*) FROM memberships m WHERE m.club_id=c.id AND m.status="approved") members,(SELECT COUNT(*) FROM attendance a JOIN events e ON e.id=a.event_id WHERE e.club_id=c.id) registered,(SELECT COUNT(*) FROM attendance a JOIN events e ON e.id=a.event_id WHERE e.club_id=c.id AND a.status="attended") attended FROM clubs c ORDER BY c.name') as $r):?><tr><?php foreach($r as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><h2>Record attendance</h2><div class="table-wrap"><table><thead><tr><th>Student</th><th>Session</th><th>When</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach(rows('SELECT a.*,u.name,e.title,e.starts_at FROM attendance a JOIN users u ON u.id=a.user_id JOIN events e ON e.id=a.event_id ORDER BY e.starts_at DESC') as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['title'])?></td><td><?=e(when($r['starts_at']))?></td><td><?=badge($r['status'])?></td><td><?php if($r['status']==='registered') action_button('attendance',(int)$r['id'],'Mark attended');?></td></tr><?php endforeach;?></tbody></table></div><h2>Tournament participants</h2><div class="table-wrap"><table><thead><tr><th>Tournament</th><th>Student</th><th>Faculty</th></tr></thead><tbody><?php foreach(rows('SELECT t.name tournament,u.name,u.faculty FROM registrations r JOIN users u ON u.id=r.user_id JOIN tournaments t ON t.id=r.tournament_id ORDER BY t.name,u.name') as $r):?><tr><?php foreach($r as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><p><a href="/?page=results">View performance standings →</a></p><h2>Recent audit activity</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach(rows('SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 50') as $r):?><tr><td><?=e(when($r['created_at']))?></td><td><?=e($r['name']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else: heading('404','That page is off the field.','Use the navigation to get back to SportsHub.'); endif;?>
